def is_valid_product_key(s):
    groups = s.split('-')
    if len(groups) != 4:
        return False
    valid_chars = set('ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789')
    for g in groups:
        if len(g) != 4 or any(c not in valid_chars for c in g):
            return False
    return True

def percentile_labels_sorted(scores):
    n = len(scores)
    def percentile(value):
        count = sum(1 for s in scores if s <= value)
        return round(100 * count / n)
    labeled = [(v, percentile(v)) for v in scores]
    return sorted(labeled, key=lambda t: t[0])

