def format_percent_change(old, new):
    if old == 0:
        return 'N/A'
    change = (new - old) / old * 100
    sign = '+' if change >= 0 else '-'
    return f'{sign}{abs(change):.1f}%'

def is_valid_stopwatch_time(s):
    if ':' not in s:
        return False
    minutes, sep, seconds = s.partition(':')
    if not minutes.isdigit() or not seconds.isdigit():
        return False
    if len(seconds) != 2:
        return False
    if len(minutes) > 1 and minutes[0] == '0':
        return False
    return 0 <= int(seconds) <= 59

